#region "FormPlugin"
public class FormPlugin : System.MarshalByRefObject, JiwaFinancials.Jiwa.JiwaApplication.IJiwaFormPlugin
{

    public override object InitializeLifetimeService()
    {
        // returning null here will prevent the lease manager
        // from deleting the Object.
        return null;
    }

    public void SetupBeforeHandlers(JiwaFinancials.Jiwa.JiwaApplication.IJiwaForm JiwaForm, JiwaFinancials.Jiwa.JiwaApplication.Plugin.Plugin Plugin)
    {
		JiwaFinancials.Jiwa.JiwaSalesUI.SalesOrder.BaseSalesOrderEntryForm salesOrderForm = (JiwaFinancials.Jiwa.JiwaSalesUI.SalesOrder.BaseSalesOrderEntryForm)JiwaForm;
		//We jump in first to clear all our hero item amounts.
		salesOrderForm.SalesOrder.ReadEnd += SalesOrder_ReadEnd;
    }

    public void Setup(JiwaFinancials.Jiwa.JiwaApplication.IJiwaForm JiwaForm, JiwaFinancials.Jiwa.JiwaApplication.Plugin.Plugin Plugin)
    {
		//Create the tab
		JiwaFinancials.Jiwa.JiwaSalesUI.SalesOrder.BaseSalesOrderEntryForm salesOrderForm = (JiwaFinancials.Jiwa.JiwaSalesUI.SalesOrder.BaseSalesOrderEntryForm)JiwaForm;
				
		Infragistics.Win.UltraWinTabControl.UltraTab heroItemsTab = salesOrderForm.MainTabControl.Tabs.Add("Hero Items", "Hero Items");
		heroItemsTab.TabPage.AutoScroll = true;
		
		//Read all the hero items and add them to the correct panel
		JiwaFinancials.Jiwa.JiwaInventory.HeroItemCollection heroItems = Plugin.Manager.CollectionFactory.CreateCollection<JiwaFinancials.Jiwa.JiwaInventory.HeroItemCollection, JiwaFinancials.Jiwa.JiwaInventory.HeroItem>();
		heroItems.Read();
		
		foreach(JiwaFinancials.Jiwa.JiwaInventory.HeroItem heroItem in heroItems)
		{
			//Change the values below to change panel size and number of indicators across a panel. Autoscroll allows unlimited rows of indicators.
			System.Drawing.Size indicatorPanelSize = new System.Drawing.Size(112, 142);
			int indicatorsPerRow = 3;
			int gapBetweenIndicators = 5;
			
			if(heroItemsTab.TabPage.Controls.ContainsKey(heroItem.Category1Description) == false)
			{
				//Create a dashboard panel for this category
				JiwaFinancials.Jiwa.JiwaApplication.Entities.Inventory.Category category1 = Plugin.Manager.EntityFactory.CreateEntity<JiwaFinancials.Jiwa.JiwaApplication.Entities.Inventory.Category>();
				category1.CategoryNo = 1;
				category1.ReadRecordFromDescription(heroItem.Category1Description);
				CreateDashboardPanel(heroItemsTab, category1);
			}
			
			JiwaFinancials.Jiwa.JiwaDashboardUI.IndicatorPanel heroItemIndicatorPanel = new JiwaFinancials.Jiwa.JiwaDashboardUI.IndicatorPanel();
			heroItemIndicatorPanel.Manager = Plugin.Manager;
        	heroItemIndicatorPanel.Setup();
			heroItemIndicatorPanel.Tag = heroItem;
			heroItemIndicatorPanel.Caption = string.Format("{0}{1}{2}", heroItem.PartNo, System.Environment.NewLine, heroItem.Description);
			heroItemIndicatorPanel.CaptionUltraLabel.WrapText = false;
			
			//Tooltip
			Infragistics.Win.UltraWinToolTip.UltraToolTipInfo heroItemToolTip = new Infragistics.Win.UltraWinToolTip.UltraToolTipInfo(string.Format("{0}{1}{2}", heroItem.PartNo, System.Environment.NewLine, heroItem.Description), Infragistics.Win.ToolTipImage.Custom, "", Infragistics.Win.DefaultableBoolean.True);
			salesOrderForm.UltraToolTipManager1.SetUltraToolTip(heroItemIndicatorPanel.CaptionUltraLabel, heroItemToolTip);
			
			heroItemIndicatorPanel.UltraPictureBox1.Image = heroItem.Picture;
			heroItemIndicatorPanel.UltraPictureBox1.Appearance.ImageHAlign = Infragistics.Win.HAlign.Center;
			heroItemIndicatorPanel.Height += heroItemIndicatorPanel.CaptionUltraLabel.Height + 5;
			heroItemIndicatorPanel.CaptionUltraLabel.Top += heroItemIndicatorPanel.CaptionUltraLabel.Height + 5;
			heroItemIndicatorPanel.CaptionUltraLabel.Left = 0;
			heroItemIndicatorPanel.ValueUltraLabel.Visible = false;
			heroItemIndicatorPanel.BackColor = heroItemIndicatorPanel.CaptionUltraLabel.Appearance.BackColor;
			JiwaFinancials.Jiwa.JiwaApplication.Controls.NumericEditor heroItemNumericEditor = new JiwaFinancials.Jiwa.JiwaApplication.Controls.NumericEditor();
			heroItemNumericEditor.Name = "heroItemNumericEditor";
			heroItemNumericEditor.SpinButtonDisplayStyle = Infragistics.Win.ButtonDisplayStyle.Always;
			heroItemNumericEditor.AutoSize = false;
			heroItemNumericEditor.Size = new System.Drawing.Size(57, 35);
			heroItemNumericEditor.DecimalPlaces = heroItem.QuantityDecimalPlaces;
			heroItemIndicatorPanel.Controls.Add(heroItemNumericEditor);
			heroItemNumericEditor.Left = heroItemIndicatorPanel.Width - heroItemNumericEditor.Width;
			heroItemNumericEditor.BringToFront();
			heroItemNumericEditor.MinValue = 0;
			heroItemNumericEditor.ValueChanged += heroItemNumericEditor_ValueChanged;
			
			JiwaFinancials.Jiwa.JiwaDashboardUI.DashboardPanel dashboardPanelIBelongTo = (JiwaFinancials.Jiwa.JiwaDashboardUI.DashboardPanel)heroItemsTab.TabPage.Controls[heroItem.Category1Description];
			Infragistics.Win.Misc.UltraPanel ultraPanelIBelongTo = (Infragistics.Win.Misc.UltraPanel)dashboardPanelIBelongTo.ControlArea.ClientArea.Controls[heroItem.Category1Description];
			ultraPanelIBelongTo.ClientArea.Controls.Add(heroItemIndicatorPanel);
			
			//Position to hero item indicator panel
			int indicatorCount = ultraPanelIBelongTo.ClientArea.Controls.Count - 1; //Before I was added
			int targetRow = indicatorCount / indicatorsPerRow;
			int targetColumn = indicatorCount % indicatorsPerRow;
			
			int xCoordinate = (targetColumn * heroItemIndicatorPanel.Width) + ((targetColumn + 1) * gapBetweenIndicators);
			int yCoordinate = (targetRow * heroItemIndicatorPanel.Height) + ((targetRow + 1) * gapBetweenIndicators);
			heroItemIndicatorPanel.Location = new System.Drawing.Point(xCoordinate, yCoordinate);			
		}
		
		//Add handlers to deal with quantity changes
		salesOrderForm.LineDisplayed += SalesOrderForm_LineDisplayed;
		salesOrderForm.SalesOrder.SalesOrderLineRemoved += SalesOrder_SalesOrderLineRemoved;
		salesOrderForm.SalesOrder.Created += SalesOrder_Created;
    }
	
	public void heroItemNumericEditor_ValueChanged(object sender, System.EventArgs e)
	{
		JiwaFinancials.Jiwa.JiwaApplication.Controls.NumericEditor heroItemNumericEditor = (JiwaFinancials.Jiwa.JiwaApplication.Controls.NumericEditor)sender;
		JiwaFinancials.Jiwa.JiwaSalesUI.SalesOrder.BaseSalesOrderEntryForm salesOrderForm = (JiwaFinancials.Jiwa.JiwaSalesUI.SalesOrder.BaseSalesOrderEntryForm)JiwaFinancials.Jiwa.JiwaApplication.Manager.GetOwnerForm(heroItemNumericEditor);
		
		if(salesOrderForm.Displaying == false)
		{
			if(heroItemNumericEditor.Parent != null && heroItemNumericEditor.Parent is JiwaFinancials.Jiwa.JiwaDashboardUI.IndicatorPanel)
			{
				JiwaFinancials.Jiwa.JiwaDashboardUI.IndicatorPanel heroItemIndicatorPanel = (JiwaFinancials.Jiwa.JiwaDashboardUI.IndicatorPanel)heroItemNumericEditor.Parent;
				if(heroItemIndicatorPanel.Tag != null && heroItemIndicatorPanel.Tag is JiwaFinancials.Jiwa.JiwaInventory.HeroItem)
				{
					JiwaFinancials.Jiwa.JiwaInventory.HeroItem heroItem = (JiwaFinancials.Jiwa.JiwaInventory.HeroItem)heroItemIndicatorPanel.Tag;
					
					JiwaFinancials.Jiwa.JiwaSales.SalesOrder.SalesOrder salesOrder = salesOrderForm.SalesOrder;		
					try
					{
						heroItemNumericEditor.ValueChanged -= heroItemNumericEditor_ValueChanged;

						decimal newQuantity = 0;
						decimal.TryParse(heroItemNumericEditor.Value.ToString(), out newQuantity);
						
						bool found = false;
						foreach(JiwaFinancials.Jiwa.JiwaSales.SalesOrder.SalesOrderLine existingSalesOrderLine in salesOrder.SalesOrderLines)
						{
							if(existingSalesOrderLine.InventoryID != null && existingSalesOrderLine.InventoryID == heroItem.InventoryID) 
							{
								if(newQuantity > 0)
									existingSalesOrderLine.QuantityOrdered = newQuantity;
								else
									salesOrder.SalesOrderLines.Remove(existingSalesOrderLine);
								
								found = true;
								break;
							}
						}
						
						if(found == false)
						{
							if(newQuantity > 0)
							{
								//Create and add a sales order line
								object newKey = null;
								salesOrder.SalesOrderLines.AddInventoryItem(heroItem.InventoryID, JiwaFinancials.Jiwa.JiwaSales.SalesOrder.SalesOrderLineCollection.SalesOrderLineInventorySeedTypes.e_SalesOrderLineInventoryID, ref newKey, null, 0);
								salesOrder.SalesOrderLines[newKey.ToString()].QuantityOrdered = newQuantity;							
							}						
						}
					}
					finally
					{
						heroItemNumericEditor.ValueChanged += heroItemNumericEditor_ValueChanged;
					}
				
				}
			}			
		}
		
	}
	
	public void DisplayHeroItem(JiwaFinancials.Jiwa.JiwaSales.SalesOrder.SalesOrderLine SalesOrderLine, decimal QuantityOrdered)
	{
		JiwaFinancials.Jiwa.JiwaSales.SalesOrder.SalesOrder salesOrder = (JiwaFinancials.Jiwa.JiwaSales.SalesOrder.SalesOrder)SalesOrderLine.SalesOrderLines.SalesOrder;
		JiwaFinancials.Jiwa.JiwaSalesUI.SalesOrder.BaseSalesOrderEntryForm salesOrderForm = (JiwaFinancials.Jiwa.JiwaSalesUI.SalesOrder.BaseSalesOrderEntryForm)salesOrder.Client;
		bool oldDisplaying = salesOrderForm.Displaying;
		try
		{
			salesOrderForm.Displaying = true;
			bool found = false;
			foreach(System.Windows.Forms.Control myControl in salesOrderForm.MainTabControl.Tabs["Hero Items"].TabPage.Controls)
			{
				if(myControl is JiwaFinancials.Jiwa.JiwaDashboardUI.DashboardPanel)
				{
					JiwaFinancials.Jiwa.JiwaDashboardUI.DashboardPanel dashboardPanel = (JiwaFinancials.Jiwa.JiwaDashboardUI.DashboardPanel)myControl;
					Infragistics.Win.Misc.UltraPanel ultraPanel = (Infragistics.Win.Misc.UltraPanel)dashboardPanel.ControlArea.ClientArea.Controls[dashboardPanel.Name];
					foreach (System.Windows.Forms.Control myIndicatorControl in ultraPanel.ClientArea.Controls)
					{
						if(myIndicatorControl is JiwaFinancials.Jiwa.JiwaDashboardUI.IndicatorPanel)
						{
							JiwaFinancials.Jiwa.JiwaDashboardUI.IndicatorPanel indicatorPanel = (JiwaFinancials.Jiwa.JiwaDashboardUI.IndicatorPanel)myIndicatorControl;
							if(indicatorPanel.Tag != null && indicatorPanel.Tag is JiwaFinancials.Jiwa.JiwaInventory.HeroItem)
							{
								JiwaFinancials.Jiwa.JiwaInventory.HeroItem heroItem = (JiwaFinancials.Jiwa.JiwaInventory.HeroItem)indicatorPanel.Tag;
								if(heroItem.InventoryID != null && heroItem.InventoryID == SalesOrderLine.InventoryID)
								{
									JiwaFinancials.Jiwa.JiwaApplication.Controls.NumericEditor heroItemNumericEditor = (JiwaFinancials.Jiwa.JiwaApplication.Controls.NumericEditor)indicatorPanel.Controls["heroItemNumericEditor"];
									heroItemNumericEditor.Value = QuantityOrdered;
									
									heroItemNumericEditor.ReadOnly = true;
									
	                                if(!(salesOrder.BillType == JiwaFinancials.Jiwa.JiwaSales.SalesOrder.SalesOrder.SalesOrderBillTypes.e_SalesOrderShipWhenComplete && salesOrder.SalesOrderType != JiwaFinancials.Jiwa.JiwaSales.SalesOrder.SalesOrder.SalesOrderTypes.e_SalesOrderNormalSalesOrder && salesOrder.SelectedHistoryNo > 1))
										if(!(SalesOrderLine.KitLineType == JiwaFinancials.Jiwa.JiwaSales.SalesOrder.SalesOrder.SalesOrderKitLineTypes.e_SalesOrderKitComponent && salesOrder.SystemSettings.AllowKitComponentOverride == false))
											heroItemNumericEditor.ReadOnly = false;
										
									if(SalesOrderLine.KitLineType == JiwaFinancials.Jiwa.JiwaSales.SalesOrder.SalesOrder.SalesOrderKitLineTypes.e_SalesOrderKitComponent && salesOrder.BillType == JiwaFinancials.Jiwa.JiwaSales.SalesOrder.SalesOrder.SalesOrderBillTypes.e_SalesOrderShipWhenComplete && salesOrder.SelectedHistoryNo > 1)
										heroItemNumericEditor.ReadOnly = true;
									
									found = true;
									break;
								}
							}
						}
					}
					if(found)
						break;
				}
			}				
		}
		finally
		{
			salesOrderForm.Displaying = oldDisplaying;
		}
	}
	
	public void SalesOrderForm_LineDisplayed(object sender, System.EventArgs e, JiwaFinancials.Jiwa.JiwaSales.SalesOrder.SalesOrderLine SalesOrderLine, int Row)
	{
		if(SalesOrderLine.InventoryID != null && SalesOrderLine.InventoryID.Trim().Length > 0)
		{
			JiwaFinancials.Jiwa.JiwaSalesUI.SalesOrder.BaseSalesOrderEntryForm salesOrderForm = (JiwaFinancials.Jiwa.JiwaSalesUI.SalesOrder.BaseSalesOrderEntryForm)SalesOrderLine.SalesOrderLines.SalesOrder.Client;
			DisplayHeroItem(SalesOrderLine, SalesOrderLine.QuantityOrdered);
		}
	}
	
	public void SalesOrder_SalesOrderLineRemoved(object sender, System.EventArgs e, JiwaFinancials.Jiwa.JiwaSales.SalesOrder.SalesOrderLine SalesOrderLine)
	{
		if(SalesOrderLine.InventoryID != null && SalesOrderLine.InventoryID.Trim().Length > 0)
		{
			JiwaFinancials.Jiwa.JiwaSalesUI.SalesOrder.BaseSalesOrderEntryForm salesOrderForm = (JiwaFinancials.Jiwa.JiwaSalesUI.SalesOrder.BaseSalesOrderEntryForm)SalesOrderLine.SalesOrderLines.SalesOrder.Client;
			DisplayHeroItem(SalesOrderLine, 0);
		}		
	}
	
	public void SalesOrder_ReadEnd(object sender, System.EventArgs e)
	{
		JiwaFinancials.Jiwa.JiwaSales.SalesOrder.SalesOrder salesOrder = (JiwaFinancials.Jiwa.JiwaSales.SalesOrder.SalesOrder)sender;
		JiwaFinancials.Jiwa.JiwaSalesUI.SalesOrder.BaseSalesOrderEntryForm salesOrderForm = (JiwaFinancials.Jiwa.JiwaSalesUI.SalesOrder.BaseSalesOrderEntryForm)salesOrder.Client;
		SetAllHeroItemsQuantitiesToZero(salesOrderForm);
		LockOrUnlockQuantityEditor(salesOrderForm);
	}
	
	public void SalesOrder_Created(object sender, System.EventArgs e, JiwaFinancials.Jiwa.JiwaSales.SalesOrder.SalesOrder.NewSalesOrderTypes NewSalesOrderType, ref JiwaFinancials.Jiwa.JiwaSales.SalesQuote.SalesQuote SourceQuoteObject)
	{
		JiwaFinancials.Jiwa.JiwaSales.SalesOrder.SalesOrder salesOrder = (JiwaFinancials.Jiwa.JiwaSales.SalesOrder.SalesOrder)sender;
		JiwaFinancials.Jiwa.JiwaSalesUI.SalesOrder.BaseSalesOrderEntryForm salesOrderForm = (JiwaFinancials.Jiwa.JiwaSalesUI.SalesOrder.BaseSalesOrderEntryForm)salesOrder.Client;
		SetAllHeroItemsQuantitiesToZero(salesOrderForm);
		LockOrUnlockQuantityEditor(salesOrderForm);
	}	
	
	public void LockOrUnlockQuantityEditor(JiwaFinancials.Jiwa.JiwaSalesUI.SalesOrder.BaseSalesOrderEntryForm SalesOrderForm)
	{
		JiwaFinancials.Jiwa.JiwaSales.SalesOrder.SalesOrder salesOrder = (JiwaFinancials.Jiwa.JiwaSales.SalesOrder.SalesOrder)SalesOrderForm.SalesOrder;
		JiwaFinancials.Jiwa.JiwaSalesUI.SalesOrder.BaseSalesOrderEntryForm salesOrderForm = (JiwaFinancials.Jiwa.JiwaSalesUI.SalesOrder.BaseSalesOrderEntryForm)salesOrder.Client;
		
		bool oldDisplaying = salesOrderForm.Displaying;
		try
		{
			salesOrderForm.Displaying = true;
			
			foreach(System.Windows.Forms.Control myControl in SalesOrderForm.MainTabControl.Tabs["Hero Items"].TabPage.Controls)
			{
				if(myControl is JiwaFinancials.Jiwa.JiwaDashboardUI.DashboardPanel)
				{
					JiwaFinancials.Jiwa.JiwaDashboardUI.DashboardPanel dashboardPanel = (JiwaFinancials.Jiwa.JiwaDashboardUI.DashboardPanel)myControl;
					Infragistics.Win.Misc.UltraPanel ultraPanel = (Infragistics.Win.Misc.UltraPanel)dashboardPanel.ControlArea.ClientArea.Controls[dashboardPanel.Name];
					foreach (System.Windows.Forms.Control myIndicatorControl in ultraPanel.ClientArea.Controls)
					{
						if(myIndicatorControl is JiwaFinancials.Jiwa.JiwaDashboardUI.IndicatorPanel)
						{
							JiwaFinancials.Jiwa.JiwaDashboardUI.IndicatorPanel indicatorPanel = (JiwaFinancials.Jiwa.JiwaDashboardUI.IndicatorPanel)myIndicatorControl;
							JiwaFinancials.Jiwa.JiwaApplication.Controls.NumericEditor heroItemNumericEditor = (JiwaFinancials.Jiwa.JiwaApplication.Controls.NumericEditor)indicatorPanel.Controls["heroItemNumericEditor"];

							heroItemNumericEditor.ReadOnly = true;
							if((salesOrder.SalesOrderStatus <= JiwaFinancials.Jiwa.JiwaSales.SalesOrder.SalesOrder.SalesOrderStatuses.e_SalesOrderEntered && salesOrder.SelectedHistoryNo == salesOrder.CurrentHistoryNo) && !(salesOrder.SystemSettings.AllowModificationOfPrintedUnprocessedInvoices == false && salesOrder.PrintLogCollection.Count > 0))
								if(salesOrder.SelectedHistoryNo == 1 || (salesOrder.BillType == JiwaFinancials.Jiwa.JiwaSales.SalesOrder.SalesOrder.SalesOrderBillTypes.e_SalesOrderShipWhenComplete))
		                            if(!(salesOrder.BillType == JiwaFinancials.Jiwa.JiwaSales.SalesOrder.SalesOrder.SalesOrderBillTypes.e_SalesOrderShipWhenComplete && salesOrder.SalesOrderType != JiwaFinancials.Jiwa.JiwaSales.SalesOrder.SalesOrder.SalesOrderTypes.e_SalesOrderNormalSalesOrder && salesOrder.SelectedHistoryNo > 1))
										heroItemNumericEditor.ReadOnly = false;							
						}
					}
				}
			}				
		}
		finally
		{
			salesOrderForm.Displaying = oldDisplaying;
		}
	}
	
	public void SetAllHeroItemsQuantitiesToZero(JiwaFinancials.Jiwa.JiwaSalesUI.SalesOrder.BaseSalesOrderEntryForm SalesOrderForm)
	{
		JiwaFinancials.Jiwa.JiwaSales.SalesOrder.SalesOrder salesOrder = (JiwaFinancials.Jiwa.JiwaSales.SalesOrder.SalesOrder)SalesOrderForm.SalesOrder;
		JiwaFinancials.Jiwa.JiwaSalesUI.SalesOrder.BaseSalesOrderEntryForm salesOrderForm = (JiwaFinancials.Jiwa.JiwaSalesUI.SalesOrder.BaseSalesOrderEntryForm)salesOrder.Client;
		
		bool oldDisplaying = salesOrderForm.Displaying;
		
		try
		{
			salesOrderForm.Displaying = true;
			
			foreach(System.Windows.Forms.Control myControl in SalesOrderForm.MainTabControl.Tabs["Hero Items"].TabPage.Controls)
			{
				if(myControl is JiwaFinancials.Jiwa.JiwaDashboardUI.DashboardPanel)
				{
					JiwaFinancials.Jiwa.JiwaDashboardUI.DashboardPanel dashboardPanel = (JiwaFinancials.Jiwa.JiwaDashboardUI.DashboardPanel)myControl;
					Infragistics.Win.Misc.UltraPanel ultraPanel = (Infragistics.Win.Misc.UltraPanel)dashboardPanel.ControlArea.ClientArea.Controls[dashboardPanel.Name];
					foreach (System.Windows.Forms.Control myIndicatorControl in ultraPanel.ClientArea.Controls)
					{
						if(myIndicatorControl is JiwaFinancials.Jiwa.JiwaDashboardUI.IndicatorPanel)
						{
							JiwaFinancials.Jiwa.JiwaDashboardUI.IndicatorPanel indicatorPanel = (JiwaFinancials.Jiwa.JiwaDashboardUI.IndicatorPanel)myIndicatorControl;
							JiwaFinancials.Jiwa.JiwaApplication.Controls.NumericEditor heroItemNumericEditor = (JiwaFinancials.Jiwa.JiwaApplication.Controls.NumericEditor)indicatorPanel.Controls["heroItemNumericEditor"];
							heroItemNumericEditor.Value = 0;
						}
					}
				}
			}				
		}
		finally
		{
			salesOrderForm.Displaying = oldDisplaying;
		}
	}
	
	public void CreateDashboardPanel(Infragistics.Win.UltraWinTabControl.UltraTab TargetTab, JiwaFinancials.Jiwa.JiwaApplication.Entities.Inventory.Category Category1)
	{
		//Change the values below to change panel size and number of panels across the screen. Autoscroll allows unlimited rows of panels.
		System.Drawing.Size dashboardPanelSize = new System.Drawing.Size(375, 265);
		int panelsPerRow = 4;
		int gapBetweenPanels = 5;
		
		JiwaFinancials.Jiwa.JiwaDashboardUI.DashboardPanel newDashboardPanel = new JiwaFinancials.Jiwa.JiwaDashboardUI.DashboardPanel();
		newDashboardPanel.Name = Category1.Description;
		newDashboardPanel.Title = Category1.Description;
		newDashboardPanel.Size = dashboardPanelSize;
		
		Infragistics.Win.Misc.UltraPanel newUltraPanel = new Infragistics.Win.Misc.UltraPanel();
		newUltraPanel.Name = Category1.Description;
		newUltraPanel.AutoScroll = true;
		
		newDashboardPanel.ControlArea.ClientArea.Controls.Add(newUltraPanel);
		newUltraPanel.Dock = System.Windows.Forms.DockStyle.Fill;
		
		TargetTab.TabPage.Controls.Add(newDashboardPanel);
		
		//Position the dashboard panel
		int panelCount = TargetTab.TabPage.Controls.Count - 1; //Before I was added
		int targetRow = panelCount / panelsPerRow;
		int targetColumn = panelCount % panelsPerRow;
		
		int xCoordinate = (targetColumn * dashboardPanelSize.Width) + ((targetColumn + 1) * gapBetweenPanels);
		int yCoordinate = (targetRow * dashboardPanelSize.Height) + ((targetRow + 1) * gapBetweenPanels);
		newDashboardPanel.Location = new System.Drawing.Point(xCoordinate, yCoordinate);				
	}
}
