namespace JiwaFinancials.Jiwa.JiwaInventory
{
	public class HeroItemCollection : JiwaFinancials.Jiwa.JiwaApplication.JiwaCollection<HeroItem>
	{
		public override void Read()
		{
			
			string Sql = null;
			SqlDataReader SQLReader = null;
			bool oldReading = Reading;
			
			try 
			{
				Reading = true;
				Clear();

				var db = Manager.Database;

				Sql = @"SELECT IN_Main.InventoryID, IN_Main.PartNo, IN_Main.Description, IN_Main.DecimalPlaces, IN_Main.Picture, IN_Category1.Description [Category1Description]
						FROM IN_Main 
						JOIN IN_Category1 ON IN_Main.Catagory1ID = IN_Category1.Category1ID
						WHERE InventoryID IN (SELECT InventoryID FROM IN_CustomSettingValues WHERE SettingID = (SELECT TOP 1 SettingID FROM IN_CustomSetting WHERE SettingName = 'Hero Item') AND Contents = 'True') 
						ORDER BY PartNo ";

				using (SqlCommand SQLCmd = new SqlCommand(Sql, db.SQLConnection, db.SQLTransaction)) {
					SQLCmd.CommandTimeout = db.DefaultCommandTimeout;

					SQLReader = SQLCmd.ExecuteReader();

					while (SQLReader.Read() == true) {
						HeroItem heroItem = Manager.CollectionItemFactory.CreateCollectionItem<HeroItem>();
						
						heroItem.InventoryID = db.Sanitise(SQLReader, "InventoryID").ToString();
						heroItem.PartNo = db.Sanitise(SQLReader, "PartNo").ToString();
						heroItem.Description = db.Sanitise(SQLReader, "Description").ToString();
						heroItem.QuantityDecimalPlaces = Convert.ToInt16(db.Sanitise(SQLReader, "DecimalPlaces"));
                      	try
						{
							heroItem.Picture = (byte[])db.Sanitise(SQLReader, "Picture");
						}
                        catch(Exception ex)
						{
							heroItem.Picture = null;
						}
						heroItem.Category1Description = db.Sanitise(SQLReader, "Category1Description").ToString();
						
						Add(heroItem);
					}

					SQLReader.Close();
				}

				base.OnRead();

			} 
			finally 
			{
				Reading = oldReading;

				if (SQLReader != null) 
					SQLReader.Close();
			}
		}		
	}
		
	public class HeroItem : JiwaFinancials.Jiwa.JiwaApplication.JiwaCollectionItem<HeroItem>
	{
		private string _InventoryID;
		private string _PartNo;
		private string _Description;
		private int _QuantityDecimalPlaces;
		private byte[] _Picture;
		private string _Category1Description;
			
		public string InventoryID 
		{
			get { return _InventoryID; }
			set {_InventoryID = value;
				NotifyPropertyChanged("InventoryID"); }
		}			
		
		public string PartNo 
		{
			get { return _PartNo; }
			set {_PartNo = value;
				NotifyPropertyChanged("PartNo"); }
		}	
		
		public string Description 
		{
			get { return _Description; }
			set {_Description = value;
				NotifyPropertyChanged("Description"); }
		}	
		
		public int QuantityDecimalPlaces 
		{
			get { return _QuantityDecimalPlaces; }
			set {_QuantityDecimalPlaces = value;
				NotifyPropertyChanged("QuantityDecimalPlaces"); }
		}	
		
		public byte[] Picture 
		{
			get { return _Picture; }
			set {_Picture = value;
				NotifyPropertyChanged("Picture"); }
		}	
		
		public string Category1Description 
		{
			get { return _Category1Description; }
			set {_Category1Description = value;
				NotifyPropertyChanged("Category1Description"); }
		}				
		
		protected override void iSave()
		{
			throw new NotImplementedException();
		}

	}		
}
